export function mephistoNative(r,n){
 const want=r?.level===0?S0:r?.level===1?S1:null;
 const skillsOk=want&&r.skills.length===want.length&&r.skills.every((s,i)=>same(s,want[i])||dustOk(s,want[i]));
 if(!isMephisto(r)||!want||r.applyWay!=="RANGED"||r.stats.rangeRadius!==3||r.notCountInTotal||!same(r.abilities,MEPHISTO_ABILITIES)
  ||!same(r.talents.bb,TALENTS)||!same(r.talents.bbStr,{"rage_aura.bgm":"lullaby"})||!skillsOk)return false;
 if(!same(closure(n),COMPONENTS)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&Object.entries(CLOCK.durations).every(([k,v])=>clock.durations[k]===v)
  &&Object.entries(CLOCK.events).every(([k,v])=>clock.events[k]?.length===1&&clock.events[k][0].name==="OnAttack"&&clock.events[k][0].time===v);
}
